script:
function setupForm({ doc, createToast, call, $dialog }) {
    return {
        actions: [
            {
                label: "Click to Call",
                icon: "phone",
                onClick: () => {

                    if (!doc || !doc.mobile_no) {
                        createToast({
                            title: "No Mobile Number",
                            message: "Selected lead has no mobile number.",
                            icon: "x",
                            iconClasses: "text-red-600",
                        });
                        return;
                    }

                    let destination_number = doc.mobile_no; // Lead's mobile number

                    // Show confirmation dialog
                    $dialog({
                        title: "Confirm Call",
                        message: `Are you sure you want to call ${destination_number}?`,
                        actions: [
                            {
                                label: "Call Now",
                                theme: "green",
                                variant: "solid",
                                onClick: (context) => {
                                    context.close(); // Close dialog before making the API call

                                    // ✅ Fetch logged-in user's mobile number
                                    call("crm_override.api.session.get_user_mobile", {})
                                        .then((response) => {
                                            let agent_number = response?.mobile_no;

                                            if (!agent_number) {
                                                createToast({
                                                    title: "Agent Number Missing",
                                                    message: "Your profile does not have a mobile number.",
                                                    icon: "x",
                                                    iconClasses: "text-red-600",
                                                });
                                                return;
                                            }

                                            // ✅ Initiate the call
                                            call("crm_override.api.tele_smartflow.connect_to_call1", {
                                                agent_number: agent_number,
                                                destination_number: destination_number
                                            })
                                            .then((response) => {
                                                let data = JSON.parse(response);
                                                console.log("Click to call response data: ", data)

                                                if (data?.success === true) {
                                                    createToast({
                                                        title: "Call Initiated",
                                                        message: `Calling ${destination_number}...`,
                                                        icon: "phone",
                                                        iconClasses: "text-green-600",
                                                    });
                                                } else {
                                                    createToast({
                                                        title: "Call Failed",
                                                        message: data?.message || "Unable to initiate the call.",
                                                        icon: "x",
                                                        iconClasses: "text-red-600",
                                                    });
                                                }
                                            })
                                            .catch((error) => {
                                                console.error("API Error:", error);
                                                createToast({
                                                    title: "Error",
                                                    message: "An error occurred while making the call.",
                                                    icon: "alert-circle",
                                                    iconClasses: "text-red-600",
                                                });
                                            });
                                        })
                                        .catch((error) => {
                                            console.error("User Fetch Error:", error);
                                            createToast({
                                                title: "Error",
                                                message: "Failed to fetch agent mobile number.",
                                                icon: "alert-circle",
                                                iconClasses: "text-red-600",
                                            });
                                        });
                                },
                            },
                            {
                                label: "Cancel",
                                variant: "outline",
                                onClick: (context) => {
                                    context.close();
                                },
                            },
                        ],
                    });
                },
            },
        ],
    };
}
